def subtract(a, b):
    # Merge all intervals in a
    def merge_intervals(intervals):
        if not intervals:
            return []

        # Filter out empty intervals and sort
        valid = [iv for iv in intervals if iv[0] < iv[1]]
        if not valid:
            return []

        valid.sort()
        merged = [valid[0]]

        for start, end in valid[1:]:
            if start <= merged[-1][1]:
                # Overlapping or touching, merge
                merged[-1][1] = max(merged[-1][1], end)
            else:
                # Disjoint, add new interval
                merged.append([start, end])

        return merged

    # Merge intervals in a and b
    a_merged = merge_intervals(a)
    b_merged = merge_intervals(b)

    if not a_merged:
        return []
    if not b_merged:
        return a_merged

    result = []

    for a_start, a_end in a_merged:
        # Current segment of a that we're processing
        current = a_start

        for b_start, b_end in b_merged:
            if b_end <= current:
                # b interval is entirely before current position
                continue
            if b_start >= a_end:
                # b interval is entirely after current segment
                break

            if b_start > current:
                # There's a gap before b starts
                result.append([current, b_start])

            # Move current to the end of b (or a_end if b extends beyond)
            current = max(current, b_end)

        # Add remaining part of a segment if any
        if current < a_end:
            result.append([current, a_end])

    return result

